  nc = `テーマイベント：%1$s`,
  rc = `ハロウィン2022`,
  ic = `このイベントは、ハロウィン2022用のゲームのアップデートに関するものですか？ハロウィン用に新しいマップや、スキン、アートワーク、その他のコンテンツをゲームに追加する場合や、ハロウィンがテーマの特別なコンテンツ、チャレンジ、その他のアクティビティのような期間限定イベントを実施する場合は、是非お知らせください。テーマに沿ったイベントが、より広いオーディエンスの目に留まるようにする方法を模索していますが、まずは、開発者がゲーム内で季節のイベントを祝うために、どのようなアクティビティを主催しているのかを、こちらで把握する必要があります。このイベントが、ハロウィン2022用のあなたのゲームへのアップデートに関するものである場合は、以下で「ON」をクリックしてください。`,
